package com.example.starter.deicing.model;

/**
 * 除冰类型。
 */
public enum DeiceType {

    /** 一步法：单步作业，无防冰液保持时间（HOT）约束。 */
    ONE_STEP,

    /** 两步法：两步作业，必须在 HOT 内完成起飞。 */
    TWO_STEP
}

package com.example.starter.deicing.model;

/**
 * 排队记录状态。非终态状态视为“进行中”，同一航班只允许存在一条进行中记录。
 */
public enum QueueStatus {

    /** 排队中，尚未出队确认。 */
    WAITING,

    /** 已出队确认，车位/除冰车时刻已排定，作业尚未开始。 */
    SCHEDULED,

    /** 除冰作业进行中；该占用不可被插队或改动。 */
    IN_PROGRESS,

    /** 除冰已完成，等待起飞回报。 */
    DEICED,

    /** HOT 风险：预计起飞将超出防冰液保持时间，须按最早可重排时刻重新除冰。 */
    HOT_RISK,

    /** 终态：已起飞。 */
    DEPARTED,

    /** 终态：已取消。 */
    CANCELLED,

    /** 终态：实际起飞时刻已超出 HOT，原除冰失效，须重新申请除冰。 */
    HOT_EXPIRED;

    /**
     * @return 是否终态（起飞、取消、HOT 失效）
     */
    public boolean isTerminal() {
        return this == DEPARTED || this == CANCELLED || this == HOT_EXPIRED;
    }
}

package com.example.starter.deicing.model;

/**
 * 车位/除冰车占用记录状态。
 */
public enum AssignmentState {

    /** 已预留：出队确认后、作业开始前。 */
    RESERVED,

    /** 作业进行中：占用锁定，不可被插队。 */
    ACTIVE,

    /** 作业已完成，区间为历史事实。 */
    DONE,

    /** 未开始即被取消，占用已释放。 */
    RELEASED
}

package com.example.starter.deicing.model;

/**
 * 幂等操作类型；幂等键为 (requestId, operation)。
 */
public enum OperationType {

    /** 申请除冰。 */
    APPLY,

    /** 出队确认。 */
    DISPATCH,

    /** 作业开始。 */
    START,

    /** 作业完成。 */
    COMPLETE,

    /** 前序延误导致的预计起飞时刻更新。 */
    DELAY,

    /** HOT 风险后确认重新除冰排定。 */
    RESCHEDULE,

    /** 起飞回报与判定。 */
    DEPART,

    /** 取消。 */
    CANCEL
}

package com.example.starter.deicing.model;

/**
 * 除冰类型。
 */
public enum DeiceType {

    /** 一步法：单步作业，无防冰液保持时间（HOT）约束。 */
    ONE_STEP,

    /** 两步法：两步作业，必须在 HOT 内完成起飞。 */
    TWO_STEP
}

