package com.example.starter.deicing.api;

import com.example.starter.deicing.model.DeiceType;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 除冰申请请求体。所有时刻字段均为 UTC 时区 epoch 毫秒。
 *
 * @param requestId          申请幂等键，由客户端给定
 * @param flightNo           航班号
 * @param stand              机位号
 * @param deiceType          除冰类型：ONE_STEP 一步法 / TWO_STEP 两步法
 * @param requiredBays       所需车位数（1 或 2）
 * @param targetDepartureTs  目标起飞时刻（UTC epoch 毫秒）
 */
public record ApplyRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 32) String flightNo,
        @NotBlank @Size(max = 32) String stand,
        @NotNull DeiceType deiceType,
        @Min(1) int requiredBays,
        @NotNull Long targetDepartureTs
) {
}

package com.example.starter.deicing.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 仅携带 requestId 的操作请求体（出队确认、作业开始、作业完成、重新除冰确认）。
 *
 * @param requestId 申请幂等键
 */
public record RequestIdRequest(@NotBlank String requestId) {
}

package com.example.starter.deicing.api;

import jakarta.validation.constraints.NotNull;

/**
 * 起飞回报请求体。
 *
 * @param requestId          申请幂等键
 * @param actualDepartureTs  实际起飞时刻（UTC epoch 毫秒）
 */
public record DepartRequest(
        @NotNull String requestId,
        @NotNull Long actualDepartureTs
) {
}

package com.example.starter.deicing.api;

import jakarta.validation.constraints.NotNull;

/**
 * 取消请求体。
 *
 * @param requestId 申请幂等键
 * @param reason    取消原因，可空
 */
public record CancelRequest(
        @NotNull String requestId,
        String reason
) {
}

package com.example.starter.deicing.api;

import jakarta.validation.constraints.NotNull;

/**
 * 前序延误回报：更新航班最新预计起飞时刻，系统据此重新评估 HOT 风险。
 *
 * @param requestId             申请幂等键
 * @param expectedDepartureTs   最新预计起飞时刻（UTC epoch 毫秒）
 */
public record DelayRequest(
        @NotNull String requestId,
        @NotNull Long expectedDepartureTs
) {
}

