package com.example.starter.deicing.api;

import com.example.starter.deicing.model.AssignmentState;

/**
 * 车位/除冰车占用半开区间视图 [startTs, endTs)。
 *
 * @param requestId  对应申请号
 * @param roundNo    除冰轮次：首次为 1，重新除冰递增
 * @param bayId      车位编号
 * @param truckId    除冰车编号
 * @param startTs    占用起点（含）
 * @param endTs      占用终点（不含），端点相接不冲突
 * @param state      占用状态
 */
public record AssignmentView(
        String requestId,
        int roundNo,
        String bayId,
        String truckId,
        long startTs,
        long endTs,
        AssignmentState state
) {
}

package com.example.starter.deicing.api;

import java.util.List;

/**
 * 队列快照：按出队优先级排序，重复查询结果稳定可复算。
 *
 * @param nowTs   快照生成时刻（UTC epoch 毫秒）
 * @param items   排队记录视图列表（非终态优先并按规则排序）
 */
public record SnapshotResponse(long nowTs, List<QueueItemResponse> items) {
}

