 */
@TestConfiguration
public class TestClockConfiguration {

    /**
     * @return 可控时钟单例，测试类可直接注入并拨时
     */
    @Bean
    @Primary
    public MutableServiceClock mutableServiceClock() {
        return new MutableServiceClock();
    }

