        mvc().perform(get("/api/deicing/timeline").param("bayId", "B1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].requestId").value("W3"))
                .andExpect(jsonPath("$[0].bayId").value("B1"));
    }
}

